[{"id":"regiment1-0","name":"1st Regiment","legend":"Regiment was formed in 1438 Pondo Era during the Tornalian Conflict. \r\n\r\nRegiment composition in 1444 PE:\r\n— infantry: 372\r\n— cavalry: 7\r\n— archers: 250."},{"id":"regiment2-0","name":"1st (Huela) Regiment","legend":"Regiment was formed in 1170 Pondo Era during the Milan War. 1st (Huela) Regiment is stationed in Huela. \r\n\r\nRegiment composition in 1444 PE:\r\n— archers: 1529\r\n— cavalry: 218\r\n— infantry: 1589\r\n— artillery: 7."},{"id":"regiment2-1","name":"2nd Regiment","legend":"Regiment was formed in 1166 Pondo Era during the Milan War. \r\n\r\nRegiment composition in 1444 PE:\r\n— archers: 363\r\n— cavalry: 52\r\n— infantry: 374."},{"id":"regiment2-2","name":"3rd Regiment","legend":"Regiment was formed in 1441 Pondo Era during the Chuenia-Tornalian War. \r\n\r\nRegiment composition in 1444 PE:\r\n— archers: 57\r\n— cavalry: 1\r\n— infantry: 41."},{"id":"regiment3-0","name":"1st (Ogolbatilia) Regiment","legend":"Regiment was formed in 1353 Pondo Era during the Hueqian War. 1st (Ogolbatilia) Regiment is stationed in Ogolbatilia Land. \r\n\r\nRegiment composition in 1444 PE:\r\n— infantry: 436\r\n— cavalry: 40\r\n— archers: 329."},{"id":"regiment3-1","name":"2nd (Vejosbar) Regiment","legend":"Regiment was formed in 1352 Pondo Era during the Hueqian War. 2nd (Vejosbar) Regiment is stationed in Vejosbar Area. \r\n\r\nRegiment composition in 1444 PE:\r\n— archers: 334\r\n— infantry: 356\r\n— cavalry: 7."},{"id":"regiment3-2","name":"3rd (Malmendia) Regiment","legend":"Regiment was formed in 1353 Pondo Era during the Hueqian War. 3rd (Malmendia) Regiment is stationed in Malmendia Territory. \r\n\r\nRegiment composition in 1444 PE:\r\n— archers: 128\r\n— infantry: 109\r\n— cavalry: 2."},{"id":"regiment3-3","name":"4th (Malopedia) Regiment","legend":"Regiment was formed in 1352 Pondo Era during the Hueqian War. 4th (Malopedia) Regiment is stationed in Malopedia Territory. \r\n\r\nRegiment composition in 1444 PE:\r\n— archers: 117\r\n— infantry: 98\r\n— cavalry: 4."},{"id":"regiment3-4","name":"5th (Tentelasia) Regiment","legend":"Regiment was formed in 1353 Pondo Era during the Hueqian War. 5th (Tentelasia) Regiment is stationed in Tentelasia Dependency. \r\n\r\nRegiment composition in 1444 PE:\r\n— archers: 90\r\n— infantry: 105\r\n— cavalry: 6."},{"id":"regiment4-0","name":"1st (Cerzia) Regiment","legend":"Regiment was formed in 1266 Pondo Era during the Hueqian Campaign. 1st (Cerzia) Regiment is stationed in Cerzia Territory. \r\n\r\nRegiment composition in 1444 PE:\r\n— archers: 1517\r\n— cavalry: 146\r\n— infantry: 1315\r\n— artillery: 1."},{"id":"regiment4-1","name":"2nd (Viavila) Regiment","legend":"Regiment was formed in 1442 Pondo Era during the Chuenia-Tornalian War. 2nd (Viavila) Regiment is stationed in Viavila Dependency. \r\n\r\nRegiment composition in 1444 PE:\r\n— archers: 1187\r\n— cavalry: 145\r\n— infantry: 1153\r\n— artillery: 3."},{"id":"regiment4-2","name":"3rd (Paroria) Regiment","legend":"Regiment was formed in 1267 Pondo Era during the Hueqian Campaign. 3rd (Paroria) Regiment is stationed in Paroria Land. \r\n\r\nRegiment composition in 1444 PE:\r\n— archers: 236\r\n— cavalry: 14\r\n— infantry: 173."},{"id":"regiment4-3","name":"1st Fleet","legend":"Regiment was formed in 1265 Pondo Era during the Hueqian Campaign. 1st Fleet is based in Midamida. \r\n\r\nRegiment composition in 1444 PE:\r\n— fleet: 1."},{"id":"marker0","name":"Manda Hot Springs","legend":"A geothermal springs with naturally heated water that provide relaxation and medicinal benefits. Average temperature is 20°C."},{"id":"marker1","name":"Cerrio Purifying Well","legend":"This legendary water source is whispered about in ancient tales and believed to possess mystical properties. The spring emanates crystal-clear water, shimmering with an otherworldly iridescence that sparkles even in the dimmest light."},{"id":"marker2","name":"Tenzaveramean Lighthouse","legend":"A lighthouse to serve as a beacon for ships in the open sea."},{"id":"marker3","name":"Salmerondean Waterfall","legend":"A river drops down from a great height forming a wonderous waterfall."},{"id":"marker4","name":"Madranta Battlefield","legend":"A historical battle of the Hueqian War. \r\nDate: May 13, 1352 Pondo Era."},{"id":"marker5","name":"Dungeon","legend":"<div>Undiscovered dungeon. See <a href=\"https://watabou.github.io/one-page-dungeon/?seed=4150068592114\" target=\"_blank\">One page dungeon</a></div><iframe style=\"pointer-events: none;\" src=\"https://watabou.github.io/one-page-dungeon/?seed=4150068592114\" sandbox=\"allow-scripts allow-same-origin\"></iframe>"},{"id":"marker6","name":"Dungeon","legend":"<div>Undiscovered dungeon. See <a href=\"https://watabou.github.io/one-page-dungeon/?seed=4150068591259\" target=\"_blank\">One page dungeon</a></div><iframe style=\"pointer-events: none;\" src=\"https://watabou.github.io/one-page-dungeon/?seed=4150068591259\" sandbox=\"allow-scripts allow-same-origin\"></iframe>"},{"id":"marker7","name":"Driejontes Monster","legend":"Whispers say a relic monster of 5 m long inhabits Driejontes Lake. Truth or lie, folks are afraid to fish in the lake."},{"id":"marker8","name":"Bodgere Monster","legend":"Old sailors tell stories of a gigantic sea monster inhabiting these dangerous waters. Rumors say it can be 35 m long."},{"id":"marker9","name":"Nunorevil Hag","legend":"Tales speak of a horrifying Hag who inhabits Nunorevil hills and terrorizes the region."},{"id":"marker10","name":"Hegudo Forest","legend":"A forest sacred to local Astellian Faith."},{"id":"marker11","name":"Pirates","legend":"Pirate ships have been spotted in these waters."},{"id":"marker12","name":"Vallara Effigy","legend":"An ancient effigy. It has an inscription, but no one can translate it:\n        <div style=\"font-size: 1.8em; line-break: anywhere;\">༸༦༈༴༻༳༿༺༁༁༱༓༶༶༪༮༙༭༱༆༠༹༼༄༐༷༭༙༩༦༲༑༽༻༅༜༽༦་༁༫༗༥༮༪༉༫༢༬༦༳༇ༀ༇༂༆༯༒༜༪༙༪༁༦༥༼་༈༅༔༺༆༦༌༲༇༃༢༌༖༦༉༼༧༈༘༂༫༦༄༼༗</div>"},{"id":"marker13","name":"Saumandie Pillar","legend":"An ancient pillar. It has an inscription, but no one can translate it:\n        <div style=\"font-size: 1.8em; line-break: anywhere;\">ⳚⳈⳫⲴⳈⳜⲸⳔⳐⳠⳒⳠⳐⳖⳠⳞⲶⳞⳃⳬ⳩ⳃⳊⳌⳆ⳩ⳤⲺ ⳥ⳠⳎⲺⲴⳃⲾⳖⳎⳲⳆ⳪ⳁⳢⲸⳁⲾ⳧⳹Ⲵ ⳪Ⲵ</div>"},{"id":"marker14","name":"Ruined Fortress","legend":"Ruins of an ancient fortress. Untold riches may lie within."},{"id":"marker15","name":"Ruined Settlement","legend":"Ruins of an ancient settlement. Untold riches may lie within."},{"id":"marker16","name":"Rats migration","legend":"A huge group of rats are migrating, whether part of their annual routine, or something more extraordinary."},{"id":"marker17","name":"Cantivias Sepulchre","legend":"A sprawling necropolis built within a labyrinthine network of catacombs. Its halls are lined with countless alcoves, each housing the remains of the departed, while the distant sound of rattling bones fills the air."},{"id":"marker18","name":"Random encounter","legend":"<div>You have encountered a character.</div><iframe src=\"https://deorum.vercel.app/encounter/2484\" width=\"375\" height=\"600\" sandbox=\"allow-scripts allow-same-origin allow-popups\"></iframe>"},{"id":"marker19","name":"Random encounter","legend":"<div>You have encountered a character.</div><iframe src=\"https://deorum.vercel.app/encounter/832\" width=\"375\" height=\"600\" sandbox=\"allow-scripts allow-same-origin allow-popups\"></iframe>"},{"id":"marker20","name":"Random encounter","legend":"<div>You have encountered a character.</div><iframe src=\"https://deorum.vercel.app/encounter/1193\" width=\"375\" height=\"600\" sandbox=\"allow-scripts allow-same-origin allow-popups\"></iframe>"}]
